=<!DOCTYPE html>
<html lang="fr">
  <body
    style="
      margin: 0;
      padding: 0;
      background-color: #f5f7f4;
      font-family: Arial, Helvetica, sans-serif;
      color: #243e35;
    "
  >
    <table
      role="presentation"
      width="100%"
      cellspacing="0"
      cellpadding="0"
      border="0"
      style="
        width: 100%;
        background-color: #f5f7f4;
        padding: 40px 16px;
      "
    >
      <tr>
        <td align="center">

          <table
            role="presentation"
            width="100%"
            cellspacing="0"
            cellpadding="0"
            border="0"
            style="
              width: 100%;
              max-width: 600px;
              background-color: #ffffff;
              border: 1px solid #e1e7e2;
              border-radius: 16px;
              overflow: hidden;
            "
          >

            <!-- Header -->
            <tr>
              <td
                style="
                  padding: 28px 32px;
                  border-bottom: 1px solid #e7ebe7;
                "
              >
                <table
                  role="presentation"
                  cellspacing="0"
                  cellpadding="0"
                  border="0"
                >
                  <tr>
                    <td
                      style="
                        width: 42px;
                        height: 42px;
                        background-color: #285448;
                        border-radius: 10px;
                        text-align: center;
                        vertical-align: middle;
                        color: #ffffff;
                        font-size: 20px;
                        font-weight: 700;
                      "
                    >
                      Z
                    </td>

                    <td style="padding-left: 12px;">
                      <div
                        style="
                          font-size: 18px;
                          font-weight: 700;
                          color: #243e35;
                        "
                      >
                        ZenKnowledge
                      </div>

                      <div
                        style="
                          margin-top: 2px;
                          font-size: 12px;
                          color: #748078;
                        "
                      >
                        Espace documentaire intelligent
                      </div>
                    </td>
                  </tr>
                </table>
              </td>
            </tr>

            <!-- Content -->
            <tr>
              <td style="padding: 36px 32px;">

                <div
                  style="
                    display: inline-block;
                    padding: 6px 10px;
                    margin-bottom: 18px;
                    background-color: #eef4f0;
                    border-radius: 999px;
                    color: #365c4d;
                    font-size: 12px;
                    font-weight: 600;
                  "
                >
                  Invitation
                </div>

                <h1
                  style="
                    margin: 0 0 18px 0;
                    color: #243e35;
                    font-size: 26px;
                    line-height: 1.25;
                    font-weight: 700;
                  "
                >
                  Bienvenue sur ZenKnowledge
                </h1>

                <p
                  style="
                    margin: 0 0 16px 0;
                    color: #59675e;
                    font-size: 15px;
                    line-height: 1.7;
                  "
                >
                  Bonjour
                  <strong style="color: #243e35;">
                    {{ $json.body.nom }}
                  </strong>,
                </p>

                <p
                  style="
                    margin: 0 0 24px 0;
                    color: #59675e;
                    font-size: 15px;
                    line-height: 1.7;
                  "
                >
                  Un compte ZenKnowledge vient d'être créé pour vous.
                  Vous pouvez maintenant activer votre accès et choisir
                  votre mot de passe.
                </p>

                <!-- Account info -->
                <table
                  role="presentation"
                  width="100%"
                  cellspacing="0"
                  cellpadding="0"
                  border="0"
                  style="
                    margin: 0 0 28px 0;
                    background-color: #f7f9f6;
                    border: 1px solid #e2e7e2;
                    border-radius: 12px;
                  "
                >
                  <tr>
                    <td style="padding: 18px 20px;">
                      <div
                        style="
                          margin-bottom: 6px;
                          color: #7a857e;
                          font-size: 12px;
                          font-weight: 600;
                          text-transform: uppercase;
                          letter-spacing: 0.5px;
                        "
                      >
                        Adresse de connexion
                      </div>

                      <div
                        style="
                          color: #243e35;
                          font-size: 15px;
                          font-weight: 600;
                        "
                      >
                        {{ $json.body.email }}
                      </div>
                    </td>
                  </tr>
                </table>

                <!-- CTA -->
                <table
                  role="presentation"
                  cellspacing="0"
                  cellpadding="0"
                  border="0"
                  style="margin-bottom: 28px;"
                >
                  <tr>
                    <td
                      align="center"
                      bgcolor="#285448"
                      style="
                        border-radius: 10px;
                      "
                    >
                      <a
                        href="{{ $json.body.invitationUrl }}"
                        target="_blank"
                        style="
                          display: inline-block;
                          padding: 14px 24px;
                          color: #ffffff;
                          text-decoration: none;
                          font-size: 14px;
                          font-weight: 700;
                          border-radius: 10px;
                        "
                      >
                        Activer mon compte
                      </a>
                    </td>
                  </tr>
                </table>

                <!-- Security info -->
                <table
                  role="presentation"
                  width="100%"
                  cellspacing="0"
                  cellpadding="0"
                  border="0"
                  style="
                    background-color: #faf8f1;
                    border: 1px solid #eee8d7;
                    border-radius: 10px;
                  "
                >
                  <tr>
                    <td style="padding: 16px 18px;">
                      <div
                        style="
                          margin-bottom: 4px;
                          color: #806122;
                          font-size: 13px;
                          font-weight: 700;
                        "
                      >
                        Lien sécurisé
                      </div>

                      <div
                        style="
                          color: #766b4f;
                          font-size: 13px;
                          line-height: 1.6;
                        "
                      >
                        Ce lien est valable pendant
                        <strong>24 heures</strong>
                        et ne peut être utilisé qu'une seule fois.
                      </div>
                    </td>
                  </tr>
                </table>

                <p
                  style="
                    margin: 28px 0 8px 0;
                    color: #879189;
                    font-size: 12px;
                    line-height: 1.6;
                  "
                >
                  Si le bouton ne fonctionne pas, copiez ce lien dans votre
                  navigateur :
                </p>

                <p
                  style="
                    margin: 0;
                    word-break: break-all;
                    color: #496c60;
                    font-size: 12px;
                    line-height: 1.6;
                  "
                >
                  {{ $json.body.invitationUrl }}
                </p>
              </td>
            </tr>

            <!-- Footer -->
            <tr>
              <td
                style="
                  padding: 22px 32px;
                  background-color: #fafbfa;
                  border-top: 1px solid #e7ebe7;
                "
              >
                <p
                  style="
                    margin: 0 0 4px 0;
                    color: #59675e;
                    font-size: 13px;
                    font-weight: 600;
                  "
                >
                  L'équipe ZenKnowledge
                </p>

                <p
                  style="
                    margin: 0;
                    color: #929b95;
                    font-size: 11px;
                  "
                >
                  Cet email a été envoyé automatiquement.
                  Merci de ne pas y répondre.
                </p>
              </td>
            </tr>

          </table>

        </td>
      </tr>
    </table>
  </body>
</html>
